import java.util.Objects;
import java.util.Optional;

public class UserService {

    public String getUserDisplay(User user) {
        // Pattern 1: Explicit null check
        if (user == null) {
            return "Guest";
        }
        return user.getName();
    }

    public void processOrder(Order order) {
        // Pattern 2: Objects.requireNonNull for parameters
        Objects.requireNonNull(order, "Order cannot be null");
        var total = order.getTotal(); // safe now
    }

    public Optional<String> findUserEmail(Long userId) {
        // Pattern 3: Optional for possibly-absent values
        var user = repository.findById(userId);
        return user != null ? Optional.of(user.getEmail()) : Optional.empty();
    }

    public void displayEmail(Long userId) {
        findUserEmail(userId)
            .ifPresent(email -> System.out.println("Email: " + email)); // no NPE risk
    }
}

public class OrderProcessor {

    public void processOrders(String[] orderIds) {
        // WRONG: off-by-one error
        // for (int i = 0; i <= orderIds.length; i++) { ... }

        // Pattern 1: Classic for loop with correct bound
        for (int i = 0; i < orderIds.length; i++) {
            System.out.println("Processing: " + orderIds[i]); // safe
        }

        // Pattern 2: Enhanced for loop (safest - no index management)
        for (var orderId : orderIds) {
            System.out.println("Order: " + orderId);
        }
    }

    public String getOrderAtPosition(String[] orders, int index) {
        // Pattern 3: Explicit bounds check before access
        if (index < 0 || index >= orders.length) {
            return "Invalid position";
        }
        return orders[index];
    }

    public void displayFirstOrder(String[] orders) {
        // Pattern 4: Check array is not empty
        if (orders.length > 0) {
            System.out.println(orders[0]); // safe
        }
    }
}

import java.util.List;

public class PaymentProcessor {

    public void processPayment(Object payment) {
        // WRONG: cast without checking
        // CreditCard card = (CreditCard) payment; // ClassCastException if not CreditCard

        // Pattern 1: instanceof check before casting (Java 15 and earlier)
        if (payment instanceof CreditCard) {
            CreditCard card = (CreditCard) payment;
            card.charge();
        } else if (payment instanceof BankTransfer) {
            BankTransfer transfer = (BankTransfer) payment;
            transfer.initiate();
        }

        // Pattern 2: Java 16+ pattern matching (check + cast in one step)
        if (payment instanceof CreditCard card) {
            card.charge(); // card is already cast and in scope
        } else if (payment instanceof BankTransfer transfer) {
            transfer.initiate();
        }
    }

    public void processOrders(List<Order> orders) {
        // Pattern 3: Generics prevent ClassCastException at compile time
        for (Order order : orders) {
            order.process(); // type-safe, no casting needed
        }
    }
}

public class FactorialCalculator {

    // WRONG: infinite recursion - no base case
    public int factorialBroken(int n) {
        return n * factorialBroken(n - 1); // StackOverflowError
    }

    // CORRECT: proper base case
    public int factorialRecursive(int n) {
        if (n <= 1) { // base case prevents infinite recursion
            return 1;
        }
        return n * factorialRecursive(n - 1);
    }

    // BETTER: iterative approach for deep calls
    public int factorialIterative(int n) {
        int result = 1;
        for (int i = 2; i <= n; i++) {
            result *= i; // no call stack growth
        }
        return result;
    }

    // Example: deep recursion even with base case
    public int sumToN(int n) {
        if (n == 0) return 0;
        return n + sumToN(n - 1); // StackOverflowError if n is very large (e.g., 100000)
    }
}

public class OrderController {

    public void processOrder(String quantityStr, String priceStr) {
        // Pattern 1: try-catch for user input
        try {
            int quantity = Integer.parseInt(quantityStr);
            double price = Double.parseDouble(priceStr);
            var total = quantity * price;
            System.out.println("Total: " + total);
        } catch (NumberFormatException e) {
            System.err.println("Invalid input: " + e.getMessage()); // show user-friendly error
        }
    }

    public Optional<Integer> parseQuantitySafely(String input) {
        // Pattern 2: return Optional instead of throwing
        try {
            return Optional.of(Integer.parseInt(input));
        } catch (NumberFormatException e) {
            return Optional.empty(); // caller handles absence
        }
    }

    public int parseWithDefault(String input, int defaultValue) {
        // Pattern 3: provide default value for invalid input
        try {
            return Integer.parseInt(input);
        } catch (NumberFormatException e) {
            return defaultValue;
        }
    }
}

import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;

public class OrderService {

    public void removeInvalidOrders(List<Order> orders) {
        // WRONG: modifying collection in for-each loop
        // for (var order : orders) {
        //     if (order.isInvalid()) orders.remove(order); // ConcurrentModificationException
        // }

        // Pattern 1: Iterator.remove()
        var iterator = orders.iterator();
        while (iterator.hasNext()) {
            var order = iterator.next();
            if (order.isInvalid()) {
                iterator.remove(); // safe - iterator knows about removal
            }
        }
    }

    public void removeExpiredOrders(List<Order> orders) {
        // Pattern 2: removeIf() (cleanest for simple predicates)
        orders.removeIf(order -> order.isExpired());
    }

    public void removeLargeOrders(List<Order> orders) {
        // Pattern 3: collect to remove, then remove all
        var toRemove = new ArrayList<Order>();
        for (var order : orders) {
            if (order.getTotal() > 10000) {
                toRemove.add(order);
            }
        }
        orders.removeAll(toRemove); // single modification after iteration
    }
}
